alter table achievements
  drop constraint if exists achievements_category_check,
  add constraint achievements_category_check
    check (category in ('career', 'daily', 'training', 'duel', 'tournament', 'shop', 'rating', 'level'));

update achievements
   set category = 'career', updated_at = now()
 where id in ('first-goal', 'amateur-ticket', 'pro-ticket');

update achievements
   set availability = 'hidden', updated_at = now()
 where id in (
   'steady-tempo',
   'almost-perfect-training',
   'handled-pressure',
   'economical-master',
   'master-arsenal',
   'no-room-for-error'
 );

