on conflict (id) do update
   set photo_url = excluded.photo_url,
       title = excluded.title,
       description = excluded.description,
       requirement = excluded.requirement,
       category = excluded.category,
       availability = excluded.availability,
       future_tag = excluded.future_tag,
       updated_at = now();

create table achievement_stages (
  achievement_id text not null references achievements(id) on delete cascade,
  stage_number int not null check (stage_number > 0),
  requirement text not null,
  target jsonb not null,
  reward_currency int not null default 0 check (reward_currency >= 0),
  reward_stars int not null default 0 check (reward_stars >= 0),
  reward_experience int not null default 0 check (reward_experience >= 0),
  reward_tokens int not null default 0 check (reward_tokens >= 0),
  is_enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (achievement_id, stage_number)
);

create table user_achievement_stages (
  user_id uuid not null references users(id) on delete cascade,
  achievement_id text not null,
  stage_number int not null,
  opened_at timestamptz not null,
  progress jsonb not null default '{}'::jsonb,
  completed_at timestamptz,
  claimed_at timestamptz,
  completion_context jsonb not null default '{}'::jsonb,
  reward_snapshot jsonb,
  primary key (user_id, achievement_id, stage_number),
  foreign key (achievement_id, stage_number)
    references achievement_stages(achievement_id, stage_number) on delete restrict,
  check (claimed_at is null or completed_at is not null)
);

create index user_achievement_stages_current_idx
  on user_achievement_stages (user_id, achievement_id, stage_number desc);

create table achievement_stage_events (
  user_id uuid not null references users(id) on delete cascade,
  achievement_id text not null references achievements(id) on delete cascade,
  event_key text not null,
  stage_number int not null,
  occurred_at timestamptz not null,
  created_at timestamptz not null default now(),
  primary key (user_id, achievement_id, event_key),
  foreign key (achievement_id, stage_number)
    references achievement_stages(achievement_id, stage_number) on delete cascade
);

alter table achievement_token_ledger
  drop constraint if exists achievement_token_ledger_user_id_achievement_id_key,
  add column if not exists stage_number int;

alter table achievement_token_ledger
  add constraint achievement_token_ledger_user_achievement_stage_key
    unique nulls not distinct (user_id, achievement_id, stage_number),
  add constraint achievement_token_ledger_stage_fk
    foreign key (achievement_id, stage_number)
    references achievement_stages(achievement_id, stage_number) on delete restrict;

