      "achievementId" text,
      "stageNumber" int,
      requirement text,
      target jsonb,
      "rewardCurrency" int,
      "rewardStars" int,
      "rewardExperience" int,
      "rewardTokens" int
    )
)
insert into achievement_stages
  (achievement_id, stage_number, requirement, target, reward_currency, reward_stars,
   reward_experience, reward_tokens)
select "achievementId", "stageNumber", requirement, target, "rewardCurrency", "rewardStars",
       "rewardExperience", "rewardTokens"
  from stage_seed
on conflict (achievement_id, stage_number) do update
   set requirement = excluded.requirement,
       target = excluded.target,
       reward_currency = excluded.reward_currency,
       reward_stars = excluded.reward_stars,
       reward_experience = excluded.reward_experience,
       reward_tokens = excluded.reward_tokens,
       updated_at = now();

with legacy_mapping(legacy_id, staged_id) as (
  values
    ('daily-sniper-streak', 'daily-sniper-streak'),
    ('ice-hand', 'ice-hand'),
    ('third-period-decides', 'third-period-decides'),
    ('final-push', 'final-push'),
    ('no-panic', 'no-panic'),
    ('dry-finish', 'dry-finish'),
    ('keeping-fit', 'keeping-fit'),
    ('sniper-week', 'sniper-week'),
    ('sniper-month', 'sniper-month'),
    ('training-monster', 'training-monster'),
    ('rhythm-control', 'rhythm-control'),
    ('cold-start', 'cold-start'),
    ('no-warmup-needed', 'no-warmup-needed'),
    ('finish-machine', 'finish-machine'),
    ('underdog', 'underdog'),
    ('classic-speed', 'classic-speed'),
    ('stable-student', 'stable-student'),
    ('training-before-battle', 'training-before-battle'),
    ('dangerous-host', 'dangerous-host'),
    ('dangerous-guest', 'dangerous-guest'),
    ('blowout', 'blowout'),
    ('hunter-streak', 'hunter-streak'),
    ('no-room-for-error', 'no-error-classic')
)
insert into user_achievement_stages
  (user_id, achievement_id, stage_number, opened_at, progress, completed_at, claimed_at,
   completion_context, reward_snapshot)
select ua.user_id,
       mapping.staged_id,
       1,
       ua.completed_at,
       '{}'::jsonb,
       ua.completed_at,
       ua.claimed_at,
       ua.completion_context,
       case when ua.claimed_at is not null then
         jsonb_build_object(
           'currency', stage.reward_currency,
           'stars', stage.reward_stars,
           'experience', stage.reward_experience,
           'tokens', stage.reward_tokens
         )
       else null end
  from user_achievements ua
  join legacy_mapping mapping on mapping.legacy_id = ua.achievement_id
  join achievement_stages stage
    on stage.achievement_id = mapping.staged_id and stage.stage_number = 1
on conflict (user_id, achievement_id, stage_number) do nothing;

insert into user_achievement_stages
  (user_id, achievement_id, stage_number, opened_at)
select migrated.user_id, migrated.achievement_id, 2, migrated.claimed_at
  from user_achievement_stages migrated
  join achievement_stages next_stage
    on next_stage.achievement_id = migrated.achievement_id and next_stage.stage_number = 2
 where migrated.stage_number = 1 and migrated.claimed_at is not null
on conflict (user_id, achievement_id, stage_number) do nothing;

insert into user_achievement_stages
  (user_id, achievement_id, stage_number, opened_at)
select users.id, stages.achievement_id, 1, now()
  from users
  join achievement_stages stages on stages.stage_number = 1 and stages.is_enabled
 where not exists (
   select 1
     from user_achievement_stages existing
    where existing.user_id = users.id
      and existing.achievement_id = stages.achievement_id
 )
on conflict (user_id, achievement_id, stage_number) do nothing;
